mapper.select:
select count(*) from tb_courier_trade_order where courier_id = #{courierId}
and trade_complete_time between concat(#{firstDayOfMonth}, ' 00:00:00') and concat(#{lastDayOfMonth}, ' 23:59:59')
and trade_cancel_time between concat(#{firstDayOfMonth}, ' 00:00:00') and concat(#{lastDayOfMonth}, ' 23:59:59')
and waybill_status = #{status}
